mapper.select:
SELECT id, household_id, earner_user_id, category_id, amount, content, memo, income_date, created_at
FROM incomes
WHERE id = #{id}

SELECT id, household_id, earner_user_id, category_id, amount, content, memo, income_date, created_at
FROM incomes
WHERE household_id = #{householdId}
  AND earner_user_id = #{earnerUserId}

    AND category_id = #{categoryId}

ORDER BY income_date DESC, id DESC
